pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this));
        vm.assume(caller != address(0));

        // Fund the contract
        vm.deal(address(c), 1 ether);

        // Attempt withdrawal as non-owner
        vm.prank(caller);
        bool reverted;
        try c.withdrawAll(caller) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The rule: non-owners must not be able to withdraw (call should revert)
        assertTrue(reverted);
    }
}

