pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 fundAmount) public {
        vm.assume(caller != address(this));
        vm.assume(fundAmount > 0 && fundAmount <= address(this).balance);
        vm.deal(address(c), fundAmount);
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSelector(c.withdrawAll.selector, address(1)));
        assertTrue(!success);
    }
}

