// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient, uint256 initialBalance) public {
        // We only care about calls where the caller is NOT the owner (address(this) is owner)
        address caller = address(0x1);
        vm.assume(recipient != address(0));
        vm.assume(caller != address(this));
        // Give the contract some balance
        vm.deal(address(c), initialBalance);
        // Pre-state: record balance
        uint256 balanceBefore = address(c).balance;
        // Perform call from non-owner
        vm.prank(caller);
        // This call should succeed in the buggy version but revert in the reference
        // We wrap it to capture revert
        bool reverted = false;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // The rule: In the reference, a non-owner call must revert; in the buggy version it may not.
        // We assert that the reference always reverts.
        assertTrue(reverted, "Non-owner caller should revert");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.deal(address(c), amount);
        vm.prank(caller);
        bool reverted;
        try c.withdrawAll(caller) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue((caller == address(this)) ? !reverted : reverted);
    }
}
